-- =====================================================================
-- Helper Academy — v33: partner meters
--   word partners can sit on a meter, like words do: light rain → steady rain → heavy rain → pouring rain.
--   word_partners gets a tags column using the same "📶 <meter>: <level>" format as words.
--   112 partners on 37 meters (new phrases are added, existing ones get their level).
-- Generated by tools/words/build_v33.py from tools/words/partners.py. Safe to re-run. Run AFTER v32.
-- =====================================================================
alter table public.word_partners add column if not exists tags text[] not null default '{}';

-- the meters below are the full truth for these words: first clear their old meter levels
update public.word_partners p set tags = array(select t from unnest(p.tags) t where t not like '📶 %')
from public.words w where w.id = p.word_id and w.lang = 'en' and w.sense = ''
  and lower(w.headword) in ('attention', 'decision', 'effort', 'fortunate', 'fun', 'homework', 'idea', 'impact', 'laugh', 'mistake', 'nervous', 'noise', 'obvious', 'question', 'rain', 'sleep', 'snow', 'speak', 'storm', 'sun', 'test', 'trouble', 'voice', 'wind') and exists (select 1 from unnest(p.tags) t where t like '📶 %');

insert into public.word_partners (word_id, kind, phrase, partner, partner_word_id, position, tags, owner_id)
select w.id, x.kind, x.phrase, x.partner,
       (select d.id from public.words d where d.lang = 'en' and d.sense = '' and d.id <> w.id and lower(d.headword) = lower(case when x.kind = 'idiom' then x.phrase else x.partner end) limit 1),
       x.pos, array[x.tag], (select p.id from public.profiles p join auth.users u on u.id = p.id where u.email = 'albarq2000@hotmail.com')
from (values
  ('rain', 'adjective', 'light rain', 'light', '📶 Rain · light → pouring: 1', 500),
